module div_16bit(
    input [15:0] A,
    input [7:0] B,
    output [15:0] result,
    output [15:0] odd
);

reg [15:0] dividend;
reg [7:0] divisor;
reg [15:0] quotient;
reg [15:0] remainder;

always @(A or B) begin
    dividend <= A;
    divisor <= B;
end

always @(dividend or divisor) begin
    if (dividend[15:8] >= divisor) begin
        quotient <= 16'b1;
        remainder <= dividend[15:8] - divisor;
    end else begin
        quotient <= 16'b0;
        remainder <= dividend[15:8];
    end
    remainder <= {remainder[7:0], dividend[7:0]};
    dividend <= {1'b0, dividend[15:1]};
end

assign result = quotient;
assign odd = remainder;

endmodule
